import os

# =============================================================================
# DIRECTORY AND FILE PATHS
# =============================================================================
# Base directories
INPUT_DIR = "./input"
METADATA_DIR = "./metadata"
WORKING_DIR = "./working/idea_3"
SUBMISSION_DIR = "./submission"

# Ensure output directories exist
os.makedirs(WORKING_DIR, exist_ok=True)
os.makedirs(SUBMISSION_DIR, exist_ok=True)

# Metadata file paths (generated by metadata script)
TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

# Submission file paths
SAMPLE_SUBMISSION_CSV = os.path.join(INPUT_DIR, "sample_submission.csv")
SUBMISSION_CSV = os.path.join(SUBMISSION_DIR, "submission.csv")

# Cache file paths (for deterministic data processing)
X_TRAIN_CACHE = os.path.join(WORKING_DIR, "X_train_transformed.npy")
Y_TRAIN_CACHE = os.path.join(WORKING_DIR, "y_train.npy")
X_VAL_CACHE = os.path.join(WORKING_DIR, "X_val_transformed.npy")
Y_VAL_CACHE = os.path.join(WORKING_DIR, "y_val.npy")
X_TEST_CACHE = os.path.join(WORKING_DIR, "X_test_transformed.npy")
TEST_IDS_CACHE = os.path.join(WORKING_DIR, "test_ids.npy")
CLASSES_CACHE = os.path.join(WORKING_DIR, "classes.npy")

# =============================================================================
# DATA CONFIGURATION
# =============================================================================
# Column definitions
ID_COL = "id"
TARGET_COL = "species"
FILE_PATH_COL = "file_path"

# Columns to exclude when extracting feature vectors
# We drop ID, Target, and File Paths to leave only the 192 numerical features
EXCLUDE_COLS = [ID_COL, TARGET_COL, FILE_PATH_COL, "full_path"]

# =============================================================================
# RANDOM SEED
# =============================================================================
SEED = 42

# =============================================================================
# MODEL HYPERPARAMETERS
# =============================================================================
# Strategy: Bagged Linear Discriminant Analysis (LDA) Ensemble

# Bagging Classifier Settings
N_ESTIMATORS = 50  # Number of base estimators in the ensemble
MAX_SAMPLES = 1.0  # Draw 100% of samples (with replacement) for each estimator
BOOTSTRAP = True  # Enable bootstrapping
N_JOBS = -1  # Use all available CPU cores

# Base Estimator (LDA) Settings
# 'lsqr': Least squares solution, supports shrinkage
LDA_SOLVER = "lsqr"
# 'auto': Automatic shrinkage using the Ledoit-Wolf lemma (crucial for p > n or high correlation)
LDA_SHRINKAGE = "auto"

# =============================================================================
# PREPROCESSING HYPERPARAMETERS
# =============================================================================
# Power Transformer Settings
# 'yeo-johnson' works with positive and negative values
PT_METHOD = "yeo-johnson"
PT_STANDARDIZE = True  # Apply zero-mean, unit-variance scaling after transformation

# Evaluation Metric Clipping
# Probabilities are clipped to [eps, 1-eps] to avoid log(0)
LOG_LOSS_EPSILON = 1e-15
